models.css:
.card {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 19px; line-height: 1.5; color: #1f2933; background: #eef1f5;
  text-align: left; margin: 0; padding: 0;
}
.wrap { --c: #334155; --cl: #93a4b8; max-width: 700px; margin: 18px auto 28px; padding: 0 14px; }
.v-FUND { --c: #475569; --cl: #a7b4c6; }
.v-DANO { --c: #be123c; --cl: #fb7185; }
.v-DDR  { --c: #9d174d; --cl: #f472b6; }
.v-REV  { --c: #5b6b7d; --cl: #a9b8c8; }
.v-BER  { --c: #0e7c86; --cl: #5fd0d8; }
.v-NER  { --c: #c2610f; --cl: #fdba74; }
.v-MMR  { --c: #5e548e; --cl: #b3a8e6; }
.v-DSB  { --c: #b91c1c; --cl: #fca5a5; }
.v-NHEJ { --c: #d7263d; --cl: #fb8a98; }
.v-HR   { --c: #23874c; --cl: #6ee7a0; }
.v-FA   { --c: #0b3a5d; --cl: #7cb8e6; }
.v-TLS  { --c: #4a5a6a; --cl: #b0bfcd; }
.v-CLIN { --c: #1d4ed8; --cl: #93b4fd; }
.v-MAPA { --c: #334155; --cl: #a7b4c6; }
.v-CASO { --c: #0f766e; --cl: #5eead4; }

.hdr { display: flex; justify-content: space-between; align-items: center; margin: 0 2px 8px; gap: 8px; }
.pill { display: inline-block; background: var(--c); color: #fff; font-size: 12px; font-weight: 700;
  letter-spacing: .05em; text-transform: uppercase; padding: 4px 11px; border-radius: 999px; }
.kind { font-size: 11px; color: #8a96a3; text-transform: uppercase; letter-spacing: .1em; white-space: nowrap; }
.panel { background: #fff; border-radius: 14px; padding: 18px 20px 14px; border-top: 5px solid var(--c);
  box-shadow: 0 1px 3px rgba(15,23,42,.08), 0 8px 22px rgba(15,23,42,.06); }
.q { font-size: 21px; font-weight: 650; }
.a { font-size: 20px; }
.a b, .a strong { color: var(--c); }
hr#answer { border: none; border-top: 1px dashed #c3cbd4; margin: 16px 0 12px; }
.cz { font-size: 20px; }
.cloze { font-weight: 700; color: var(--c); }
.box { margin-top: 14px; border-radius: 10px; padding: 11px 14px; font-size: 16px; line-height: 1.45; }
.box-t { font-size: 11px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; margin-bottom: 4px; opacity: .8; }
.why   { background: #f3f6f9; border-left: 4px solid var(--c); }
.mnemo { background: #fff7e0; border-left: 4px solid #e9a800; }
.pearl { background: #eaf8f0; border-left: 4px solid #23874c; }
.src { margin-top: 12px; font-size: 12px; color: #8a96a3; text-align: right; }
.vignette { background: #f7f9fb; border: 1px solid #e1e6ec; border-radius: 10px; padding: 12px 14px;
  font-size: 17px; margin-bottom: 12px; }
.warn { color: #b91c1c; font-weight: 700; }
table { border-collapse: collapse; width: 100%; font-size: 15px; margin: 6px 0 2px; }
th, td { border: 1px solid #dde3ea; padding: 5px 8px; vertical-align: top; text-align: left; }
th { background: #edf1f5; font-weight: 700; }
ul, ol { margin: 6px 0 0; padding-left: 22px; }
li { margin: 2px 0; }
.flow { display: flex; flex-wrap: wrap; align-items: center; gap: 5px; margin: 6px 0 2px; }
.chip { background: var(--c); color: #fff; border-radius: 7px; padding: 2px 8px; font-size: 14px; font-weight: 600; }
.chip.soft { background: #e5eaf0; color: #1f2933; }
.arr { color: #8a96a3; font-weight: 700; }
.nt { display: inline-block; min-width: 1.7em; text-align: center; font-family: ui-monospace, Menlo, Consolas, monospace;
  font-weight: 700; border-radius: 6px; padding: 1px 6px; color: #fff; background: #0b3a5d; margin: 0 1px; }
.nt.bad { background: #d7263d; } .nt.ok { background: #23874c; } .nt.alt { background: #d9731a; } .nt.mut { background: #5e548e; }
.small { font-size: 14px; color: #52606d; }

/* ---------- modo nocturno ---------- */
.nightMode.card, .night_mode.card, .card.nightMode, .card.night_mode { background: #0f141a; color: #e4e9ef; }
.nightMode .panel, .night_mode .panel { background: #1a222c; box-shadow: none; border-top-color: var(--cl); }
.nightMode .cloze, .night_mode .cloze, .nightMode .a b, .night_mode .a b,
.nightMode .a strong, .night_mode .a strong { color: var(--cl); }
.nightMode .why, .night_mode .why { background: #222c38; border-left-color: var(--cl); }
.nightMode .mnemo, .night_mode .mnemo { background: #332b14; }
.nightMode .pearl, .night_mode .pearl { background: #14301f; }
.nightMode .vignette, .night_mode .vignette { background: #202a35; border-color: #2f3b48; }
.nightMode th, .night_mode th { background: #253140; }
.nightMode th, .nightMode td, .night_mode th, .night_mode td { border-color: #34414f; }
.nightMode .chip.soft, .night_mode .chip.soft { background: #2c3846; color: #e4e9ef; }
.nightMode .small, .night_mode .small { color: #a9b4c0; }
.nightMode .warn, .night_mode .warn { color: #fca5a5; }
.nightMode hr#answer, .night_mode hr#answer { border-top-color: #3b4756; }

@media (max-width: 480px) {
  .card { font-size: 18px; } .q { font-size: 19px; } .a, .cz { font-size: 18px; }
  .panel { padding: 15px 15px 12px; } .box { font-size: 15px; } table { font-size: 13px; }
}

